function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function rewardNuggets(amount){addStoneChange(Math.max(1,Math.round(amount)),Math.min(gemTiers.length-1,selectedStageIndex()+5));}
function buildingLevel(id){return Number(state.v5.buildings[id]||0);}
function buildingUpgradeCost(building,level=buildingLevel(building?.id)){const tier=Math.max(0,Math.min(SETTLEMENT_PRICE_CURVE.length-1,Number(level)||0));return Math.round(Number(building?.base||0)*SETTLEMENT_PRICE_CURVE[tier]);}
function buildingUpgradeRequiredPlayerLevel(level=0){const tier=Math.max(0,Math.min(SETTLEMENT_LEVEL_REQUIREMENTS.length-1,Number(level)||0));return SETTLEMENT_LEVEL_REQUIREMENTS[tier];}
function buildingUpgradeUnlocked(level=0,playerLevel=state.level){return Math.max(1,Number(playerLevel)||1)>=buildingUpgradeRequiredPlayerLevel(level);}
function purchaseBuildingUpgrade(id){
 ensureV5();
 const building=BUILDINGS.find(item=>item.id===id);
 if(!building)return false;
 const level=buildingLevel(building.id);
 if(level>=SETTLEMENT_LEVEL_REQUIREMENTS.length){setMessage(`${building.name} is already fully upgraded.`,'');return false;}
 const requiredLevel=buildingUpgradeRequiredPlayerLevel(level);
 if(!buildingUpgradeUnlocked(level)){setMessage(`${building.name} Level ${level+1} requires Player Level ${requiredLevel}. Your Player Level is ${Number(state.level)||1}.`,'wrong');return false;}
 const cost=buildingUpgradeCost(building,level);
 if(!spendStoneValue(cost)){setMessage(`You need ${cost.toLocaleString()} Nuggets.`,'wrong');return false;}
 state.v5.buildings[building.id]=level+1;
 save();
 render();
 setMessage(`${building.name} upgraded to Level ${level+1}! Player Level ${requiredLevel} requirement met.`,'correct');
 return true;
}
function activeCompanion(){return COMPANIONS.find(companion=>companion.id===state.v5?.companion)||COMPANIONS[0];}
function companionEffect(name){return Number(activeCompanion().effects?.[name]||0);}
function companionAvailable(companion){return !!companion&&(state.v5.ownedCompanions.includes(companion.id)||Number(companion.requiredStage||0)===0||isStageUnlocked(Number(companion.requiredStage)));}
function companionAdjustedShopPrices(base){const supply=Math.max(0,Math.min(.25,companionEffect('supplyDiscount'))),heart=Math.max(0,Math.min(.35,supply+companionEffect('heartDiscount')));return {hint:Math.max(1,Math.round(Number(base.hint)*(1-supply))),shield:Math.max(1,Math.round(Number(base.shield)*(1-supply))),heart:Math.max(1,Math.round(Number(base.heart)*(1-heart)))};}
function applyCompanionCorrectAnswer(question,dueReview=false){const effects=activeCompanion().effects||{},stage=Math.max(0,Number(question?.stage)||0),streak=Number(state.streak||0);let xpRate=Number(effects.playerXp||0);if(streak>=Number(effects.streakRequired||Infinity))xpRate+=Number(effects.streakXp||0);const extraXp=Math.max(0,Math.round((12+stage*3)*xpRate));if(extraXp){state.xp=Number(state.xp||0)+extraXp;while(state.xp>=xpNeed()){state.xp-=xpNeed();state.level=Number(state.level||1)+1;}}let hintAwarded=0,shieldAwarded=0,reviewReward=0;const totalCorrect=Number(state.v5.totalCorrect||0),hintEvery=Number(effects.hintEvery||0),shieldEvery=Number(effects.shieldEvery||0);if(hintEvery>0&&totalCorrect>0&&totalCorrect%hintEvery===0){state.hints=Number(state.hints||0)+1;hintAwarded=1;}if(shieldEvery>0&&totalCorrect>0&&totalCorrect%shieldEvery===0){state.shields=Number(state.shields||0)+1;shieldAwarded=1;}if(dueReview&&Number(effects.dailyReviewReward||0)>0&&state.v5.companionDailyReview!==today()){reviewReward=Math.round(effects.dailyReviewReward);rewardNuggets(reviewReward);state.v5.companionDailyReview=today();}return {extraXp,hintAwarded,shieldAwarded,reviewReward};}
function dueCount(){const now=Date.now();return Object.values(state.v5.srs).filter(x=>Number(x.dueAt||0)<=now).length;}
function checkpointCount(stage){const ratio=Math.min(1,Number(state.stageXp[stage]||0)/STAGE_XP_REQUIREMENTS[stage]);return Math.max(1,Math.min(5,Math.floor(ratio*5)+1));}
