function bossChallengePassed(battle,now=Date.now()){return !!battle&&['active','passed'].includes(battle.status)&&Number(battle.questions)===BOSS_QUESTION_TARGET&&Number(battle.correct)===BOSS_QUESTION_TARGET&&(battle.status==='passed'||now<=Number(battle.deadline||0));}
