function bossChallengeFailed(battle,now=Date.now()){return !!battle&&(battle.status==='failed'||(battle.status==='active'&&((Number(battle.questions)>=BOSS_QUESTION_TARGET&&Number(battle.correct)<BOSS_QUESTION_TARGET)||now>=Number(battle.deadline||0))));}
function bossResultSummary(battle,now=Date.now()){const answered=Math.max(0,Math.min(BOSS_QUESTION_TARGET,Number(battle?.questions)||0)),correct=Math.max(0,Math.min(answered,Number(battle?.correct)||0)),incorrect=answered-correct,unanswered=BOSS_QUESTION_TARGET-answered,finishedAt=Number(battle?.finishedAt||now),elapsedMs=Math.max(0,Math.min(BOSS_TIME_LIMIT_MS,finishedAt-Number(battle?.startedAt||finishedAt))),accuracy=answered?Math.round(correct/answered*100):0;return{answered,correct,incorrect,unanswered,accuracy,elapsedMs,passed:battle?.status==='passed'||bossChallengePassed(battle,now)};}
function recordBossAnswer(battle,correct,answeredAt=Date.now()){if(!battle||battle.status!=='active')return{accepted:false,finished:false,reason:''};if(answeredAt>=Number(battle.deadline||0))return{accepted:false,finished:true,reason:'timeout'};battle.questions=Math.min(BOSS_QUESTION_TARGET,Number(battle.questions||0)+1);if(correct)battle.correct=Math.min(battle.questions,Number(battle.correct||0)+1);const finished=battle.questions>=BOSS_QUESTION_TARGET;return{accepted:true,finished,reason:finished?'completed':'',questions:battle.questions,correct:battle.correct};}
