 bossAutoAdvanceTimer=setTimeout(()=>{bossAutoAdvanceTimer=null;const current=state.v5?.boss;if(!current||current.status!=='active'||Number(current.stage)!==stage||Number(current.questions)!==answeredCount||!state.answered)return;const now=Date.now();if(now>=Number(current.deadline||0))finishBossAttempt(current,'timeout',now);else showNextBossQuestion(current);},BOSS_AUTO_ADVANCE_DELAY_MS);
