function closeCosmeticPreview(){document.getElementById('cosmeticPreviewOverlay')?.classList.remove('open');document.getElementById('cosmeticPreviewOverlay')?.setAttribute('aria-hidden','true');pendingCosmetic=null;}
function openPickaxePreview(id,source){const skin=PICKAXE_SKINS.find(item=>item.id===id);if(!skin)return false;if(state.ownedPickaxeSkins.includes(id)){equipPickaxe(id);if(document.getElementById('shopOverlay')?.classList.contains('open'))renderShop();return true;}openCosmeticPreview({type:'pickaxe',key:'pickaxe',value:skin.id,price:skin.cost,name:skin.name,description:skin.desc,icon:skin.icon,source});return true;}
function buyPreviewedCosmetic(){const item=pendingCosmetic;if(!item)return;if(item.type==='pickaxe'){if(!buyPickaxe(item.value))return;pendingCosmetic=null;document.getElementById('cosmeticPreviewOverlay')?.classList.remove('open');document.getElementById('cosmeticPreviewOverlay')?.setAttribute('aria-hidden','true');if(document.getElementById('shopOverlay')?.classList.contains('open'))renderShop();return;}const price=Number(item.price)||0;if(!spendStoneValue(price)){setMessage(`You need ${price.toLocaleString()} Nuggets.`,'wrong');return;}if(item.type==='character'){const token=`${item.key}:${item.value}`;if(!state.ownedCosmetics.includes(token))state.ownedCosmetics.push(token);state.character[item.key]=item.value;}else{const token=`${item.key}:${item.value}`;if(!state.v5.ownedFashion.includes(token))state.v5.ownedFashion.push(token);state.v5.fashion[item.key]=item.value;}const source=item.source;pendingCosmetic=null;document.getElementById('cosmeticPreviewOverlay')?.classList.remove('open');save();render();setMessage(`${item.name} purchased and equipped!`,'correct');if(item.type==='character'&&source?.isConnected)source.click();else if(document.getElementById('v5Overlay')?.classList.contains('open'))renderV5('fashion');}

function shell(){
 if(document.getElementById('v5Overlay'))return;
 document.body.insertAdjacentHTML('beforeend',`<div id="v5Overlay" class="v5-overlay" aria-hidden="true"><section class="v5-panel"><header class="v5-head"><button id="v5BackToMenu" class="menu-back-button" type="button">← Menu</button><div class="menu-header-copy"><span>Japanese Miner v5.0</span><h2>Expedition Hub</h2></div><button id="v5Close" aria-label="Close">×</button></header><nav class="v5-tabs"><button data-v5tab="map">🗺️ Expedition</button><button data-v5tab="boss">👹 Bosses</button><button data-v5tab="review">🧠 Review</button><button data-v5tab="book">📖 Word Book</button><button data-v5tab="companions">🐾 Companions</button><button data-v5tab="settlement">🏘️ Settlement</button><button data-v5tab="missions">🎯 Missions</button><button data-v5tab="events">🎊 Events</button><button data-v5tab="fashion">👘 Fashion</button></nav><main id="v5Content"></main></section></div>`);
 document.getElementById('v5Close').onclick=closeV5;document.getElementById('v5BackToMenu').onclick=()=>returnToGameMenu(closeV5);document.getElementById('v5Overlay').onclick=e=>{if(e.target.id==='v5Overlay')closeV5();};document.querySelectorAll('[data-v5tab]').forEach(b=>b.onclick=()=>renderV5(b.dataset.v5tab));
}
let currentTab='map';
function openV5(tab='map'){ensureV5();shell();document.getElementById('v5Overlay').classList.add('open');document.getElementById('v5Overlay').setAttribute('aria-hidden','false');window.syncJapaneseMinerPageScroll?.();renderV5(tab);}
function closeV5(){document.getElementById('v5Overlay')?.classList.remove('open');document.getElementById('v5Overlay')?.setAttribute('aria-hidden','true');window.syncJapaneseMinerPageScroll?.();}
let bossTimerInterval=null;
function bossHudShell(){if(document.getElementById('bossChallengeHud'))return;const challenge=document.getElementById('challengeArea');if(!challenge)return;const hud=document.createElement('section');hud.id='bossChallengeHud';hud.className='boss-challenge-hud';hud.hidden=true;hud.setAttribute('aria-live','polite');hud.innerHTML='<div><span>👹 Boss Gate</span><strong id="bossHudName">Guardian challenge</strong><small id="bossHudProgress">25 randomized course questions</small></div><strong id="bossHudTimer">5:00</strong>';challenge.before(hud);}
function renderBossHud(now=Date.now()){bossHudShell();const hud=document.getElementById('bossChallengeHud'),battle=state.v5?.boss;if(!hud)return;if(!battle||battle.status==='ready'){hud.hidden=true;return;}if(battle.status==='active'&&bossChallengeFinished(battle,now)){finishBossAttempt(battle,Number(battle.questions)>=BOSS_QUESTION_TARGET?'completed':'timeout',now);return;}const finished=['failed','passed'].includes(battle.status);hud.hidden=false;hud.classList.toggle('failed',battle.status==='failed');hud.classList.toggle('passed',battle.status==='passed');document.getElementById('bossHudName').textContent=BOSSES[battle.stage];document.getElementById('bossHudProgress').textContent=finished?`${battle.correct}/${BOSS_QUESTION_TARGET} correct · ${battle.questions}/${BOSS_QUESTION_TARGET} answered · results ready`:`${battle.correct}/${BOSS_QUESTION_TARGET} correct · ${battle.questions}/${BOSS_QUESTION_TARGET} answered · mistakes are recorded`;document.getElementById('bossHudTimer').textContent=battle.status==='passed'?'PASSED':battle.status==='failed'?'RESULTS':`${Math.ceil(bossRemainingMs(battle,now)/1000)}s`;}
function startBossClock(){if(bossTimerInterval)return;bossTimerInterval=setInterval(()=>renderBossHud(),250);}
function gemCheckpointStrip(stage){const drops=GEM_CHECKPOINT_DROPS.filter(drop=>drop.stage===Number(stage));return `<div class="map-gem-checkpoints"><strong>Scientific drops</strong><div>${drops.map(drop=>{const claimed=gemCheckpointClaimed(drop),ready=Number(state.stageXp?.[stage]||0)>=gemCheckpointThreshold(stage,drop.checkpoint);return `<span class="map-gem-drop ${claimed?'claimed':ready?'ready':''}">${gemArtMarkup(drop.gem,'map-gem-art')}<small>${claimed?'Claimed':`${drop.checkpoint*20}%`}</small><b>${esc(drop.gem)}</b></span>`;}).join('')}</div></div>`;}
function jlptSectionWorldLevels(stage,section){const spec=jlptSectionSpec(section),config=jlptSectionLessonConfig(section),levels=jlptSectionLevels(stage,section),selected=currentJlptSectionLevel(stage,section);return `<div class="jlpt-vocabulary-panel jlpt-section-lessons"><header><div><strong>${spec.name} lessons</strong><small>Matches the Course: preview every ${config.singular}, then practice the same set.</small></div><span>${levels.length} lesson${levels.length===1?'':'s'}</span></header><div class="jlpt-vocabulary-grid">${levels.map((level,index)=>{const open=jlptSectionLevelUnlocked(stage,section,index),mastery=jlptSectionLevelMastery(stage,section,index),current=index===selected,complete=mastery>=JLPT_VOCABULARY_UNLOCK_MASTERY;return `<button data-world-lesson-stage="${stage}" data-world-lesson-section="${section}" data-world-lesson-level="${index}" class="jlpt-vocabulary-level ${open?'open':'locked'} ${complete?'complete':''} ${current?'current':''}" ${open?'':'disabled'}><span>${open?index+1:'🔒'}</span><strong>Lesson ${index+1}</strong><small>${level.length} ${config.plural} · ${mastery}% mastery</small><i><b style="width:${mastery}%"></b></i></button>`;}).join('')}</div></div>`;}
function jlptVocabularyWorldLevels(stage){return jlptSectionWorldLevels(stage,'vocabulary');}
function standardWorldRoad(stage,reached,unlocked){const selected=currentJlptSection(stage),sections=JLPT_SECTION_SPECS.map((section,index)=>{const open=unlocked,current=stage===selectedStageIndex()&&section.id===selected,mastery=jlptSectionMastery(stage,section.id);return `${index>0?'<i class="road-piece"></i>':''}<button data-world-section-stage="${stage}" data-world-section="${section.id}" class="world-node jlpt-section-node ${open?'open':'locked'} ${current?'current':''}" ${open?'':'disabled'}><span>${section.icon}</span><small>${section.name} · ${mastery}%</small></button>`;}).join(''),bossOpen=unlocked&&bossUnlocked(stage);return `<div class="world-road jlpt-section-road">${sections}<i class="road-piece"></i><button data-world-stage="${stage}" data-world-point="5" class="world-node ${bossOpen?'open':'locked'}" ${bossOpen?'':'disabled'}><span>🏯</span><small>Boss</small></button></div>${stage===selectedStageIndex()?jlptSectionWorldLevels(stage,selected):''}${gemCheckpointStrip(stage)}`;}
function kanaWorldRoad(stage){const families=kanaFamiliesForStage(stage),kind=kanaKindForStage(stage),selected=Number(state.kanaFamilyLevel?.[kind]||0),stageUnlocked=isStageUnlocked(stage);const finalReady=kanaFamilyMastery(families[families.length-1])>=KANA_FAMILY_UNLOCK_MASTERY;const guardianOpen=stageUnlocked&&finalReady&&bossUnlocked(stage);return `<div class="world-road kana-world-road">${families.map((family,index)=>{const open=stageUnlocked&&kanaFamilyUnlocked(stage,index),complete=kanaFamilyMastery(family)>=KANA_FAMILY_UNLOCK_MASTERY,current=stage===selectedStageIndex()&&index===selected;return `<button data-world-family-stage="${stage}" data-world-family="${index}" class="world-node kana-world-node ${open?'open':'locked'} ${complete?'complete':''} ${current?'current':''}" ${open?'':'disabled'}><span>${family.entries[0]?.[0]||index+1}</span><small>${esc(family.name)} · ${kanaFamilyMastery(family)}%</small></button>`;}).join('')}</div><div class="kana-world-guardian"><button data-world-stage="${stage}" data-world-point="5" class="world-node ${guardianOpen?'open':'locked'}" ${guardianOpen?'':'disabled'}><span>🏯</span><small>Guardian</small></button></div>${gemCheckpointStrip(stage)}`;}
function mapView(){const scenery=['🌱','🎋','🌸','⛰️','❄️','🔥','🌌'];return `<div class="v5-hero world-hero"><div><span>Japanese Miner Map</span><h3>${stages[selectedStageIndex()].name}</h3><p>The Expedition Hub and Course share the same Vocabulary, Kanji, Grammar, and Reading lessons, unlocks, and mastery progress.</p></div><b>🗺️</b></div><div class="world-legend"><span>🟢 Available</span><span>⭐ Current</span><span>🔒 Locked</span><span>🏯 Guardian</span></div><div class="world-map-scroll"><div class="world-map-canvas"><div class="map-cloud c1">☁️</div><div class="map-cloud c2">☁️</div>${stages.map((s,i)=>{const reached=checkpointCount(i),unlocked=isStageUnlocked(i),isKana=i<2;const familyCount=isKana&&unlocked?kanaFamiliesForStage(i).filter((_,index)=>kanaFamilyUnlocked(i,index)).length:0,sectionCount=isKana?0:JLPT_SECTION_SPECS.filter(section=>jlptSectionMastery(i,section.id)>=75).length;const progressLabel=isKana?`${familyCount}/${KANA_FAMILY_SPECS.length} families`:`${sectionCount}/4 course areas mastered`;return `<section class="world-region region-${i} ${i===selectedStageIndex()?'current-region':''} ${unlocked?'':'locked-region'}"><div class="region-scenery">${scenery[i]} <small>Mine ${i+1}</small></div><div class="region-label"><strong>${esc(s.name)}</strong><span>${progressLabel}</span></div>${isKana?kanaWorldRoad(i):standardWorldRoad(i,reached,unlocked)}</section>`;}).join('')}<div class="world-finish">🏆 Master Mine</div></div></div>`;}
function bossView(){const battle=state.v5.boss;if(battle){const ready=battle.status==='ready',failed=battle.status==='failed',passed=battle.status==='passed',finished=failed||passed,remaining=Math.ceil(bossRemainingMs(battle)/1000),percent=Math.min(100,battle.questions/BOSS_QUESTION_TARGET*100),result=bossResultSummary(battle),elapsed=Math.ceil(result.elapsedMs/1000);return `<div class="boss-arena ${failed?'boss-failed':''} ${passed?'boss-passed':''}"><div class="boss-sprite">${battle.stage===6?'🐉':'👹'}</div><h3>${esc(BOSSES[battle.stage])}</h3><div class="boss-rules"><strong>Perfect Gate Challenge</strong><span>Complete up to 25 freshly randomized questions from the full ${esc(stages[battle.stage].label)} course within 5 minutes.</span><small>🔇 The test is silent. Wrong answers are recorded and the test continues. Every answer advances automatically; results appear after question 25 or when time expires. A 25/25 score unlocks the next mine.</small></div><div class="boss-metrics"><b>${result.correct}/${BOSS_QUESTION_TARGET}<small>correct</small></b><b>${result.incorrect}<small>incorrect</small></b><b>${result.answered}/${BOSS_QUESTION_TARGET}<small>answered</small></b><b>${finished?elapsed:`${ready?'300':remaining}`}s<small>${finished?'time used':'remaining'}</small></b></div><div class="boss-health"><i style="width:${percent}%"></i></div>${finished?`<section class="boss-results ${passed?'passed':'failed'}"><span>${passed?'Test passed':'Test results'}</span><h4>${result.correct}/${BOSS_QUESTION_TARGET} correct · ${result.accuracy}% accuracy</h4><p>${result.incorrect} incorrect · ${result.unanswered} unanswered · ${elapsed} seconds used</p><strong>${passed?`Perfect score! The next mine is unlocked. +${Number(battle.reward||0).toLocaleString()} Nuggets.`:esc(battle.failureReason)}</strong></section>${failed?'<button data-v5-action="retry-boss">Retry with a new random set</button>':''}`:`<button data-v5-action="fight">${ready?'Begin silent randomized test':'Continue test'}</button>`}<button data-v5-action="flee">${finished?'Close results':'Leave test'}</button></div>`;}return `<div class="boss-gate-intro"><h3>Guardian progression gates</h3><p>Every silent attempt shuffles 25 different questions from that guardian's entire course. Wrong answers are recorded, every answer advances automatically, and results appear after question 25 or at the 5-minute limit. Score 25/25 to unlock the next mine.</p></div><div class="v5-grid">${stages.map((s,i)=>{const defeated=state.v5.bossDefeated.includes(i),stageOpen=isStageUnlocked(i),unlocked=stageOpen&&bossUnlocked(i),lockedText=!stageOpen?'Defeat previous guardian':bossUnlocked(i)?'Challenge boss':'Reach boss checkpoint';return `<article class="v5-card"><span class="v5-icon">${i===6?'🐉':'👹'}</span><h3>${esc(BOSSES[i])}</h3><p>25 randomized questions from the full ${esc(s.label)} course · 5 minutes · automatic advancement · silent results test.</p><button data-start-boss="${i}" ${!unlocked||defeated?'disabled':''}>${defeated?'Defeated':unlocked?'Challenge boss':lockedText}</button></article>`;}).join('')}</div>`;}
function completeDailyRefresher(ref=state.v5?.dailyRefresher){
 if(!ref||ref.status==='complete')return false;ref.status='complete';ref.completedAt=Date.now();ref.day=today();state.active=null;state.answered=false;state.shieldArmed=false;save();render();openV5('review');setMessage(`Daily refresher complete: ${ref.correct}/${ref.questionIds.length} remembered. No hearts or lesson progress were affected.`,'correct');return true;
}
function showNextDailyRefresher(){
 ensureV5();const ref=state.v5.dailyRefresher;if(!ref||ref.status!=='active')return false;
 while(ref.index<ref.questionIds.length){const question=questions.find(item=>String(item.id)===String(ref.questionIds[ref.index])&&item.kind!=='listening-only'&&questionAllowedForSession(item));if(!question){ref.index++;continue;}state.selectedStage=Number(question.stage)||0;state.active={...question,opts:Array.isArray(question.opts)?shuffle([...question.opts]):question.opts,dailyRefresher:true};state.answered=false;state.shieldArmed=false;showQuestion(state.active);render();setMessage(`Daily refresher ${ref.index+1} of ${ref.questionIds.length} · tap an answer when ready. No microphone, timer, hearts, or progression penalties.`,'');save();return true;}
 return completeDailyRefresher(ref);
}
function startDailyRefresher(){
 clearTimeout(refresherAutoAdvanceTimer);refresherAutoAdvanceTimer=null;ensureV5();const session=previousStudySession(),items=previousSessionQuestions(session);if(!session||!items.length){setMessage('Finish a study session first. Your next visit will turn it into a Daily Refresher.','');renderV5('review');return false;}
 const existing=state.v5.dailyRefresher,sourceAt=Number(session.completedAt||session.lastAt)||0;if(existing?.status==='active'&&existing.sourceAt===sourceAt&&existing.questionIds.length){closeV5();return showNextDailyRefresher();}
 state.v5.dailyRefresher={day:today(),sourceAt,questionIds:shuffle(items.map(question=>String(question.id))).slice(0,DAILY_REFRESHER_LIMIT),index:0,correct:0,status:'active',completedAt:0};save();closeV5();return showNextDailyRefresher();
}
function answerDailyRefresher(question,opt,button){
 const ref=state.v5?.dailyRefresher;if(!ref||ref.status!=='active'||state.answered)return false;const correct=opt===question.a;state.answered=true;const buttons=[...document.querySelectorAll('#answers button')];buttons.forEach(answerButton=>{answerButton.disabled=true;if(answerButton.textContent===String(question.a))answerButton.style.background='#225f49';});if(button)button.style.background=correct?'#225f49':'#6d2933';ref.index=Math.min(ref.questionIds.length,Number(ref.index||0)+1);if(correct)ref.correct=Number(ref.correct||0)+1;save();render();setMessage(correct?`Refresher answer correct. ${ref.correct}/${ref.index} remembered so far. Next card opens automatically.`:`Refresher answer: ${question.a}. This is practice only—no heart or progress was lost. Next card opens automatically.`,correct?'correct':'wrong');clearTimeout(refresherAutoAdvanceTimer);refresherAutoAdvanceTimer=setTimeout(()=>{refresherAutoAdvanceTimer=null;showNextDailyRefresher();},REFRESHER_AUTO_ADVANCE_DELAY_MS);return true;
}
function reviewView(){
 const due=questions.filter(q=>questionAllowedForSession(q)&&Number(state.v5.srs[q.id]?.dueAt||0)<=Date.now()&&state.v5.srs[q.id]),session=previousStudySession(),previous=previousSessionQuestions(session),result=state.v5.dailyRefresher,completeToday=result?.status==='complete'&&result.day===today(),sessionDate=session?new Date(Number(session.completedAt||session.lastAt)).toLocaleDateString():'';
 const cards=previous.map(q=>`<article><strong>${esc(stripMarkup(q.displayChallenge||q.q))}</strong><span>${esc(q.prompt)}</span><small>Answer: ${esc(stripMarkup(q.a))}</small></article>`).join('');
 return `<div class="v5-hero refresher-hero"><div><span>Previous-session refresher</span><h3>${previous.length?`${previous.length} item${previous.length===1?'':'s'} from last time`:'Study once to create your refresher'}</h3><p>${previous.length?`Review what you studied ${sessionDate?`on ${sessionDate}`:'in your previous session'}, then answer at your own pace.`:'After your first completed study session, this page will prepare up to 10 familiar tap-answer questions.'}</p></div><b>🔄</b></div>${completeToday?`<div class="refresher-result"><strong>✅ Today’s refresher complete</strong><span>${result.correct}/${result.questionIds.length} remembered · review again whenever you want</span></div>`:''}<button class="v5-wide" data-v5-action="daily-refresher" ${previous.length?'':'disabled'}>${result?.status==='active'&&result.sourceAt===Number(session?.completedAt||session?.lastAt)?'Continue Daily Refresher':completeToday?'Review Previous Session Again':'Start Daily Refresher'}</button><div class="refresher-note"><strong>Relaxed practice</strong><span>No microphone, speaking test, timer, heart loss, or lesson penalty. Listening buttons may still be used elsewhere when you choose.</span></div><div class="previous-session-grid">${cards||'<p>Complete some lesson or mine questions, then return on your next play session.</p>'}</div><section class="optional-smart-review"><header><div><span>Optional long-term review</span><h3>${due.length} Smart Review${due.length===1?'':'s'} due</h3></div><b>🧠</b></header><p>These spaced-repetition questions are separate from your Daily Refresher. Missed material returns sooner and mastered material waits longer.</p><button class="v5-wide" data-v5-action="review" ${due.length?'':'disabled'}>Start Optional Smart Review</button><div class="review-queue">${due.slice(0,20).map(q=>`<div><strong>${esc(stripMarkup(q.displayChallenge||q.q))}</strong><span>${esc(q.prompt)}</span></div>`).join('')||'<p>Nothing is due right now.</p>'}</div></section>`;
}
function bookView(){const words=Object.entries(state.v5.wordBook).filter(([id,word])=>tutorAccessGranted()||(!word.tutor&&questionAllowedForSession(questions.find(question=>String(question.id)===String(id))))).map(([,word])=>word).sort((a,b)=>b.updated-a.updated);return `<div class="v5-hero"><div><span>Vocabulary collection</span><h3>${words.length} collected cards</h3><p>Correct Japanese questions automatically enter your permanent collection.</p></div><b>📖</b></div><div class="word-book">${words.map(w=>`<article><button data-speak-card="${esc(w.jp)}">🔊</button><strong>${esc(w.jp)}</strong><span>${esc(w.meaning)}</span><div><i style="width:${w.mastery}%"></i></div><small>${w.mastery}% mastery · seen ${w.seen}×</small></article>`).join('')||'<p>Answer a Japanese question correctly to collect your first card.</p>'}</div>`;}
function companionView(){return `<div class="v5-hero"><div><span>Balanced companion roster</span><h3>${COMPANIONS.length-1} companions to discover</h3><p>Only the equipped companion is active. Advanced companions require later mines and substantially more Nuggets.</p></div><b>🐾</b></div><div class="v5-grid">${COMPANIONS.map(c=>{const owned=state.v5.ownedCompanions.includes(c.id),equipped=state.v5.companion===c.id,available=companionAvailable(c),required=Number(c.requiredStage||0),requirement=required?`Requires ${stages[required].label}`:'Available from Hiragana';return `<article class="v5-card companion-card ${equipped?'equipped':''} ${available?'':'companion-locked'}"><span class="v5-icon">${c.icon}</span><h3>${c.name}</h3><p>${c.bonus}</p><small class="companion-requirement">${owned?'Owned':available?requirement:`🔒 ${requirement}`}</small><button data-companion="${c.id}" ${equipped||(!owned&&!available)?'disabled':''}>${equipped?'Adventuring with you':owned?'Choose companion':available?`Adopt — ${c.cost.toLocaleString()} Nuggets`:requirement}</button></article>`;}).join('')}</div>`;}
function settlementView(){const playerLevel=Math.max(1,Number(state.level)||1);return `<div class="v5-hero settlement-hero"><div><span>Long-term settlement</span><h3>Player Level unlocks permanent upgrades</h3><p>Upgrade tiers require Player Levels ${SETTLEMENT_LEVEL_REQUIREMENTS.join(', ')}. Existing purchased levels remain intact.</p></div><div class="settlement-player-level"><small>Player Level</small><strong>${playerLevel}</strong></div></div><div class="settlement-scene">🏔️ <span>🏡</span><span>🌸</span><span>🏛️</span><span>🔥</span></div><div class="v5-grid">${BUILDINGS.map(b=>{const lv=buildingLevel(b.id),maxed=lv>=SETTLEMENT_LEVEL_REQUIREMENTS.length,cost=buildingUpgradeCost(b,lv),requiredLevel=buildingUpgradeRequiredPlayerLevel(lv),unlocked=!maxed&&buildingUpgradeUnlocked(lv,playerLevel);return `<article class="v5-card settlement-card ${unlocked||maxed?'':'level-locked'}"><span class="v5-icon">${b.icon}</span><h3>${b.name} <small>Lv. ${lv}/5</small></h3><p>${b.desc}</p><small class="settlement-level-requirement ${unlocked||maxed?'met':'locked'}">${maxed?'All five Player Level requirements completed':unlocked?`✓ Player Level ${requiredLevel} requirement met`:`🔒 Level ${lv+1} requires Player Level ${requiredLevel} · You are Level ${playerLevel}`}</small><button data-building="${b.id}" ${maxed||!unlocked?'disabled':''}>${maxed?'Fully upgraded':unlocked?`Upgrade — ${cost.toLocaleString()} Nuggets`:`Unlocks at Player Level ${requiredLevel}`}</button></article>`;}).join('')}</div>`;}
function missionRewardFor(spec){const stage=Math.max(0,Math.min(CHEST_REWARD_BY_STAGE.length-1,Number(state.v5.missions.rewardStage)||0)),mineBase=Number(CHEST_REWARD_BY_STAGE[stage]||0),garden=1+buildingLevel('garden')*.1;return Math.round(Math.max(Number(spec.minReward)||0,mineBase*Number(spec.rewardRate||0))*garden);}
function missionRewardText(spec){const rewards=[`${missionRewardFor(spec).toLocaleString()} Nuggets`];if(spec.hints)rewards.push(`${spec.hints} Hint${spec.hints===1?'':'s'}`);if(spec.shields)rewards.push(`${spec.shields} Shield${spec.shields===1?'':'s'}`);return rewards.join(' + ');}
function claimMission(id){ensureV5();const spec=MISSION_SPECS.find(item=>item.id===id),missions=state.v5.missions;if(!spec||missions.claimed[id]||Number(missions[spec.metric]||0)<spec.goal)return false;missions.claimed[id]=true;rewardNuggets(missionRewardFor(spec));state.hints=Number(state.hints||0)+Number(spec.hints||0);state.shields=Number(state.shields||0)+Number(spec.shields||0);save();render();renderV5('missions');setMessage(`${spec.name} completed! ${missionRewardText(spec)} added.`,'correct');return true;}
function missionsView(){const m=state.v5.missions,stage=Math.max(0,Math.min(stages.length-1,Number(m.rewardStage)||0)),gardenLevel=buildingLevel('garden'),claimed=MISSION_SPECS.filter(spec=>m.claimed[spec.id]).length;return `<div class="mission-hero"><div><span>Daily expedition board</span><h3>🎯 Missions</h3><p>Finish mine-focused objectives. Nugget rewards are locked to ${esc(stages[stage]?.label||'your current mine')} for the day${gardenLevel?` and boosted ${gardenLevel*10}% by your Sakura Garden`:''}.</p></div><b>${claimed}/${MISSION_SPECS.length}</b></div>${MISSION_SPECS.map(spec=>{const value=Math.min(spec.goal,Number(m[spec.metric]||0)),done=m.claimed[spec.id];return `<article class="mission-row"><div><strong>${spec.name}</strong><span>${spec.desc}</span><small>Reward: ${missionRewardText(spec)}</small><div><i style="width:${Math.min(100,value/spec.goal*100)}%"></i></div></div><button data-mission="${spec.id}" ${value<spec.goal||done?'disabled':''}>${done?'Claimed':value>=spec.goal?'Claim rewards':`${value}/${spec.goal}`}</button></article>`;}).join('')}<h3>Expedition achievements</h3>${V5_ACHIEVEMENTS.map(([id,n,d,test,r])=>{const done=state.v5.achievements[id];return `<article class="mission-row"><div><strong>${done?'🏆':'🔒'} ${n}</strong><span>${d}</span></div><button data-achievement="${id}" ${!test()||done?'disabled':''}>${done?'Unlocked':test()?`Claim ${r.toLocaleString()}`:'In progress'}</button></article>`;}).join('')}`;}
function eventView(){const s=season(),claimed=state.v5.seasonClaim===`${s.key}:${today()}`;return `<div class="season-event" style="--season:${s.color}"><span>${s.icon}</span><h3>${s.name}</h3><p>${s.desc}</p><div class="season-progress"><i style="width:${Math.min(100,state.v5.missions.correct/5*100)}%"></i></div><button data-v5-action="season" ${state.v5.missions.correct<5||claimed?'disabled':''}>${claimed?'Today’s treasure claimed':'Claim seasonal treasure'}</button></div>`;}
function fashionThumbnail(key,id){const markup=window.japaneseMinerCharacterMarkup?.('mini')||'';return markup.replace('class="miner-avatar',`data-${key}="${id}" class="miner-avatar`);}
function fashionView(){return `<div class="v5-hero"><div><span>Expanded wardrobe</span><h3>Layer your miner’s outfit</h3><p>Every item includes a character preview before purchase.</p></div><b>👘</b></div>${Object.entries(FASHION).map(([key,items])=>`<section class="fashion-group"><h3>${key[0].toUpperCase()+key.slice(1)}</h3><div>${items.map(([id,name,cost])=>{const owned=state.v5.ownedFashion.includes(`${key}:${id}`),on=state.v5.fashion[key]===id;return `<button data-fashion-key="${key}" data-fashion-id="${id}" data-fashion-cost="${cost}" class="fashion-preview-choice ${on?'selected':''}"><div class="fashion-avatar-preview">${fashionThumbnail(key,id)}</div><strong>${name}</strong><small>${on?'Equipped':owned?'Owned':`${cost.toLocaleString()} Nuggets`}</small></button>`;}).join('')}</div></section>`).join('')}`;}
function renderV5(tab=currentTab){ensureV5();currentTab=tab;document.querySelectorAll('[data-v5tab]').forEach(b=>b.classList.toggle('active',b.dataset.v5tab===tab));const c=document.getElementById('v5Content');if(!c)return;c.innerHTML=tab==='map'?mapView():tab==='boss'?bossView():tab==='review'?reviewView():tab==='book'?bookView():tab==='companions'?companionView():tab==='settlement'?settlementView():tab==='missions'?missionsView():tab==='events'?eventView():fashionView();bindV5(c);}
function startBoss(stage){if(!isStageUnlocked(stage)||!bossUnlocked(stage))return;state.v5.boss={stage,status:'ready',questions:0,correct:0,startedAt:0,deadline:0,finishedAt:0,finishReason:'',reward:0,rewardClaimed:false,failureReason:'',questionIds:[]};state.selectedStage=stage;save();render();renderV5('boss');}
function bindV5(c){
 c.querySelectorAll('[data-world-stage]').forEach(b=>b.onclick=()=>{const stage=Number(b.dataset.worldStage),point=Number(b.dataset.worldPoint);selectStage(stage,false);if(point===5&&bossUnlocked(stage)){renderV5('boss');}else{closeV5();mine();document.getElementById('challengeArea')?.scrollIntoView({behavior:'smooth',block:'center'});}});
 c.querySelectorAll('[data-world-family-stage]').forEach(b=>b.onclick=()=>{const stage=Number(b.dataset.worldFamilyStage),family=Number(b.dataset.worldFamily);selectStage(stage,false);selectKanaFamily(stage,family);closeV5();mine();document.getElementById('challengeArea')?.scrollIntoView({behavior:'smooth',block:'center'});});
 c.querySelectorAll('[data-world-section-stage]').forEach(b=>b.onclick=()=>{const stage=Number(b.dataset.worldSectionStage),section=b.dataset.worldSection;selectStage(stage,false);if(selectJlptSection(stage,section))renderV5('map');});
 c.querySelectorAll('[data-world-lesson-stage]').forEach(b=>b.onclick=()=>{const stage=Number(b.dataset.worldLessonStage),section=b.dataset.worldLessonSection,level=Number(b.dataset.worldLessonLevel);closeV5();openJlptSectionLessonReview(stage,section,level);});
 c.querySelectorAll('[data-select-route]').forEach(b=>b.onclick=()=>{selectStage(Number(b.dataset.selectRoute),Number(b.dataset.selectRoute)===2);renderV5('map');});
 c.querySelectorAll('[data-start-boss]').forEach(b=>b.onclick=()=>startBoss(Number(b.dataset.startBoss)));
 c.querySelectorAll('[data-companion]').forEach(b=>b.onclick=()=>{const x=COMPANIONS.find(c=>c.id===b.dataset.companion);if(!x)return;const owned=state.v5.ownedCompanions.includes(x.id);if(!owned&&!companionAvailable(x)){setMessage(`${x.name} unlocks after reaching ${stages[x.requiredStage].name}.`,'wrong');return;}if(!owned&&!b.closest('#shopContent')){closeV5();openShop('companions');return;}if(!owned){if(!spendStoneValue(x.cost)){setMessage(`You need ${x.cost.toLocaleString()} Nuggets to adopt ${x.name}.`,'wrong');return;}state.v5.ownedCompanions.push(x.id);}state.v5.companion=x.id;save();render();b.closest('#shopContent')?renderShop():renderV5('companions');});
 c.querySelectorAll('[data-building]').forEach(b=>b.onclick=()=>{if(!b.closest('#shopContent')){closeV5();openShop('settlement');return;}if(purchaseBuildingUpgrade(b.dataset.building))renderShop();});
 c.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>claimMission(b.dataset.mission));
 c.querySelectorAll('[data-achievement]').forEach(b=>b.onclick=()=>{const a=V5_ACHIEVEMENTS.find(x=>x[0]===b.dataset.achievement);if(!a||state.v5.achievements[a[0]]||!a[3]())return;state.v5.achievements[a[0]]=Date.now();rewardNuggets(a[4]);save();render();renderV5('missions');});
 c.querySelectorAll('[data-speak-card]').forEach(b=>b.onclick=()=>speakJapanese(b.dataset.speakCard));
 c.querySelectorAll('[data-fashion-key]').forEach(b=>b.onclick=()=>{const key=b.dataset.fashionKey,id=b.dataset.fashionId,cost=Number(b.dataset.fashionCost),token=`${key}:${id}`;if(!state.v5.ownedFashion.includes(token)&&!b.closest('#shopContent')){closeV5();openShop('fashion');return;}if(!state.v5.ownedFashion.includes(token)){openCosmeticPreview({type:'fashion',key,value:id,price:cost,name:b.querySelector('strong')?.textContent||'Apparel',source:b});return;}state.v5.fashion[key]=id;save();render();b.closest('#shopContent')?renderShop():renderV5('fashion');});
 c.querySelectorAll('[data-v5-action]').forEach(b=>b.onclick=()=>action(b.dataset.v5Action));
}
function action(a){
 if(a==='fight'){const battle=state.v5.boss;if(!battle||!['ready','active'].includes(battle.status))return;if(battle.status==='ready'&&!beginBossAttempt(battle)){save();renderBossHud();renderV5('boss');return;}if(bossChallengeFinished(battle)){finishBossAttempt(battle,Number(battle.questions)>=BOSS_QUESTION_TARGET?'completed':'timeout');return;}save();renderBossHud();closeV5();mine();document.getElementById('challengeArea')?.scrollIntoView({behavior:'smooth'});}
 if(a==='retry-boss'){const battle=state.v5.boss;if(!battle)return;if(!beginBossAttempt(battle)){save();renderBossHud();renderV5('boss');return;}save();renderBossHud();closeV5();mine();document.getElementById('challengeArea')?.scrollIntoView({behavior:'smooth'});}
 if(a==='flee'){clearBossAutoAdvance();state.v5.boss=null;save();render();renderBossHud();renderV5('boss');}
 if(a==='daily-refresher')startDailyRefresher();
 if(a==='review'){const due=questions.filter(q=>questionAllowedForSession(q)&&state.v5.srs[q.id]&&state.v5.srs[q.id].dueAt<=Date.now());if(due.length){state.selectedStage=due[0].stage;state.active=due[Math.floor(Math.random()*due.length)];state.answered=false;showQuestion(state.active);closeV5();render();}}
 if(a==='season'){const s=season();state.v5.seasonClaim=`${s.key}:${today()}`;rewardNuggets(25000+buildingLevel('garden')*5000);state.hints+=2;save();render();renderV5('events');showChest(25000+buildingLevel('garden')*5000);}
}
function addMenu(){const grid=document.querySelector('.game-menu-grid');if(!grid||grid.querySelector('[data-v5-open]'))return;const b=document.createElement('button');b.type='button';b.dataset.v5Open='1';b.innerHTML='<span>🗺️</span><strong>Expedition Hub</strong><small>Maps, bosses, reviews, pets, and your settlement</small>';b.onclick=()=>{closeGameMenu();openV5('map');};grid.prepend(b);}

document.querySelector('.menu-wheel')?.classList.add('game-menu-grid');ensureV5();addV5Content();shell();utilityShell();calendarShell();heartHudShell();previewShell();bossHudShell();startBossClock();addMenu();addDashboardMenu();addCalendarMenu();upgradeGameMenu();
const launchButton=document.getElementById('v5LaunchBtn'),loadStatus=document.getElementById('v5LoadStatus');if(launchButton)launchButton.disabled=false;if(loadStatus)loadStatus.textContent='✅ v5 expansion loaded';document.querySelector('.v5-launch-card')?.classList.add('loaded');
const oldMineV5=mine;mine=function(){ensureV5();const battle=state.v5.boss;if(battle?.status==='active'){if(bossAutoAdvanceTimer||Number(state.active?.bossCourseStage)===Number(battle.stage)&&!state.answered)return false;return showNextBossQuestion(battle);}return oldMineV5();};
const oldChoose=chooseQuestion;chooseQuestion=function(pool){ensureV5();const due=pool.filter(q=>state.v5.srs[q.id]&&state.v5.srs[q.id].dueAt<=Date.now()),reviewChance=Math.min(.75,.62+companionEffect('reviewChance'));return due.length&&Math.random()<reviewChance?due[Math.floor(Math.random()*due.length)]:oldChoose(pool);};
const oldQuestionDisplay=questionDisplay;questionDisplay=function(q){return q?.kind==='listening-only'?'<span class="listening-mystery">🎧 Listen carefully</span>':oldQuestionDisplay(q);};
const oldAnswer=answer;
answer=function(opt,button){
 ensureV5();const q=state.active,wasAnswered=state.answered;
 if(q?.dailyRefresher===true&&!wasAnswered){answerDailyRefresher(q,opt,button);return;}
 const correct=!!q&&opt===q.a,dueReview=!!(q&&state.v5.srs[q.id]?.dueAt<=Date.now()),bossAnswerActive=state.v5.boss?.status==='active',bossResources=bossAnswerActive?{hearts:state.hearts,shields:state.shields,shieldArmed:state.shieldArmed,heartRecoveryEnd:state.heartRecoveryEnd}:null;
 oldAnswer(opt,button);if(!q||wasAnswered)return;recordStudySessionQuestion(q,correct);
 if(bossResources&&!correct){state.hearts=bossResources.hearts;state.shields=bossResources.shields;state.shieldArmed=bossResources.shieldArmed;state.heartRecoveryEnd=bossResources.heartRecoveryEnd;state.answered=true;document.querySelectorAll('#answers button').forEach(answerButton=>answerButton.disabled=true);}
 state.v5.missions.answered++;if(correct){state.v5.missions.correct++;state.v5.totalCorrect++;collectWord(q);react('happy');if(state.v5.totalCorrect%CHEST_CORRECT_INTERVAL===0)chestReward();}else react('sad');if(dueReview)state.v5.missions.reviews++;updateSrs(q,correct);if(correct)applyCompanionCorrectAnswer(q,dueReview);
 const battle=state.v5.boss;if(battle?.status==='active'){const now=Date.now(),score=recordBossAnswer(battle,correct,now);if(!score.accepted){if(score.reason==='timeout')finishBossAttempt(battle,'timeout',now);return;}state.answered=true;document.querySelectorAll('#answers button').forEach(answerButton=>answerButton.disabled=true);if(score.finished){finishBossAttempt(battle,score.reason,now);return;}react('attack');setMessage(`Boss test: ${battle.correct}/${BOSS_QUESTION_TARGET} correct · ${battle.questions}/${BOSS_QUESTION_TARGET} answered · ${Math.ceil(bossRemainingMs(battle,now)/1000)} seconds left. Next question opens automatically.`,correct?'correct':'wrong');save();render();renderBossHud();scheduleNextBossQuestion(battle);}else save();
};
